use kimo_core::commands::{Session,dispatch};use serde_json::json;
fn fixture()->(Session,String){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.4,0.2,0.1],"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();(s,c)}
#[test]fn managed_helpers_fail_without_mutation(){let(mut s,c)=fixture();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true}})).unwrap();for (name,args) in [("pick_white_balance",json!({"clip_id":c,"time":0.5})),("match_color",json!({"clip_id":c,"ref_clip_id":c,"time":0.5,"ref_time":0.5}))]{assert!(dispatch(&mut s,name,&args).is_err());assert!(s.project.find_clip(&c).unwrap().effects.is_empty());}}
#[test]fn legacy_picker_regions_and_gain(){let(mut s,c)=fixture();for r in [[-0.1,0.,0.2,0.2],[0.,0.,0.,0.2],[0.9,0.,0.2,0.2],[0.001,0.001,0.0001,0.0001]]{assert!(dispatch(&mut s,"pick_white_balance",&json!({"clip_id":c,"time":0.5,"x":r[0],"y":r[1],"w":r[2],"h":r[3]})).is_err());assert!(s.project.find_clip(&c).unwrap().effects.is_empty());}let v=dispatch(&mut s,"pick_white_balance",&json!({"clip_id":c,"time":0.5})).unwrap();assert!((v["gains"][0].as_f64().unwrap()-7./12.).abs()<1e-6);assert_eq!(s.project.find_clip(&c).unwrap().effects.len(),1);}
#[test]fn invalid_match_strength_no_mutation(){let(mut s,c)=fixture();assert!(dispatch(&mut s,"match_color",&json!({"clip_id":c,"ref_clip_id":c,"time":0.5,"ref_time":0.5,"strength":2})).is_err());assert!(s.project.find_clip(&c).unwrap().effects.is_empty());}
#[test]fn pipeline_typos_and_clip_override_domain(){let(mut s,c)=fixture();let before=serde_json::to_value(&s.project.color_pipeline).unwrap();assert!(dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamma":3}})).is_err());assert_eq!(serde_json::to_value(&s.project.color_pipeline).unwrap(),before);assert!(dispatch(&mut s,"set_clip_input_color",&json!({"clip_id":c,"gamut":3,"transfer":0})).is_err());dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true}})).unwrap();assert!(dispatch(&mut s,"set_clip_input_color",&json!({"clip_id":c,"gamut":3,"transfer":0})).is_err());assert!(!s.project.find_clip(&c).unwrap().props.contains_key("input_gamut"));}
#[test]fn clear_stale_wrapper_after_disabling_pipeline(){let(mut s,c)=fixture();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true}})).unwrap();let e=dispatch(&mut s,"add_effect",&json!({"clip_id":c,"kind":"saturation"})).unwrap()["effect_id"].clone();dispatch(&mut s,"set_effect_encoding",&json!({"clip_id":c,"effect_id":e,"gamut":0,"transfer":1})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":false}})).unwrap();assert!(dispatch(&mut s,"set_effect_encoding",&json!({"clip_id":c,"effect_id":e,"clear":true})).is_ok());assert!(!s.project.find_clip(&c).unwrap().effects[0].strings.contains_key("wrapper_working_gamut"));}
